INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('78862952-01c3-4735-b74a-0fadff67e1b9', 'Seated Side To Side Twist (Stick)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Stick Seated Side To Side Twist targets your obliques through a twisting motion, building rotational core strength. The abs assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '103551201', '103551201-Stick-Sitting-Side-to-Side-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Stick Seated Side To Side Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Stick Seated Side To Side Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('78a14f3e-12fc-4f85-a351-ec30f0aa9071', 'Wide Walking On Spot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '92491201', '92491201-Wide-Walking-On-Spot-(front-POV)-(female)_Plyometr.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Set up in the starting position for Wide Walking On Spot. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Wide Walking On Spot', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('78a24b6f-62d6-4423-a14a-7688d7dd2a96', 'Side Step Squat Arms Lateral Raise', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Traps"}'::text[], 'A challenging plyometric exercise, the Side Step Squat Arms Lateral Raise builds reactive power and improves conditioning. You''ll also feel your glutes, hamstrings working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '81761201', '81761201-Side-Step-Squat-Arms-Lateral-Raise-(female)_Plyome.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 100, 5, 7, FALSE, TRUE, 'lateral_raise', 'Side Step Squat Arms Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('78a4c9b5-69cb-47ca-b5bb-7fc7c0dbfe90', 'Standing Calf Raise With Arms Circle', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '95241201', '95241201-Standing-Calf-Raise-with-Arms-Circle-(female)_Calv.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise With Arms Circle', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('78a5ca12-bc2f-4042-a7cc-c189cce37ef7', 'Decline Bench Press - Wide Grip (Smith Machine)', 'Chest', 'Smith Machine, Decline Bench', '{Pectorals}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. Declining shifts the emphasis to hit the muscles from a different angle. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '13091201', '13091201-Smith-Wide-Grip-Decline-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Wide Grip Decline Bench Press. 2. Set the bench to a decline angle and secure your feet. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Lower the weight toward your chest with control. 5. Press the weight up until your arms are extended (don''t lock elbows). 6. Complete all reps with control before resting.', 'Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 96, 7, 9, TRUE, FALSE, 'decline_press', 'Smith Decline Bench Press - Wide Grip', 'Decline Bench Press - Wide Grip', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('78bf6441-8f75-416a-8c9d-6143aff0421e', 'Lying Leg Tuck Hip Stretch Wth Overhead Hands', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Secondary activation of your glutes provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Include this in your routine for better mobility and reduced muscle tension.', '34741201', '34741201-Lying-Leg-Tuck-Hip-Stretch-wth-Overhead-Hands-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Lie down in the appropriate position for Lying Leg Tuck Hip Stretch Wth Overhead Hands. 2. Move into the stretch position for Lying Leg Tuck Hip Stretch Wth Overhead Hands. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Lying Leg Tuck Hip Stretch Wth Overhead Hands', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('78c64ccc-aa4a-4f90-ba11-47925d460d71', 'Side Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Dumbbell Side Lunge is a lunging exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '34471201', '34471201-Dumbbell-Side-Lunge-(VERSION 3)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('78cb069d-f80d-4415-8782-6c57c322cd59', 'Seated In Out Leg Raise Over Bench - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '78031201', '78031201-Seated-Alternate-In-Out-Leg-Raise-over-Bench_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated In Out Leg Raise Over Bench - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('78d22a88-ee04-428e-8e7c-688b39d40459', 'Walking Chest Push On Spot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic pushing movement gets your heart rate up while developing explosive strength. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Perfect for including in both strength and hypertrophy programs.', '92501201', '92501201-Walking-Chest-Push-On-Spot-(front-POV)-(female)_Pl.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Chest Push On Spot. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Chest Push On Spot', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('78d3791f-7f5f-4cdc-8123-ca035dac4c0e', 'Standing Hip Horizontal Rotation', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Build leg strength with this rotation movement focusing on your full body. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '90521201', '90521201-Standing-Hip-Horizontal-Rotation-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Hip Horizontal Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Horizontal Rotation', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('78dbeeb8-ca79-4c78-8ec5-78a915d41544', 'Lunge Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts. Perfect for including in both strength and hypertrophy programs.', '104261201', '104261201-Dumbbell-Lunge-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lunge Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Lunge Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('78e2d2d2-310e-4aca-b310-a827bb4f0af1', 'Tilt And Extend', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. Perfect for including in both strength and hypertrophy programs.', '73521201', '73521201-Tilt-and-Extend-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Set up in the starting position for Tilt And Extend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Tilt And Extend', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7914cbb4-7c7d-4432-b2ff-d7756332bebd', '90 To 90 To Shin Box Step Through (Plyo Box)', 'Legs', 'Plyo Box', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Designed to lengthen your full body, the 90 To 90 To Shin Box Step Through helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '82561201', '82561201-90-to-90-to-Shin-Box-Step-Through-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Set up a box or step platform at the appropriate height. 2. Move into the stretch position for 90 To 90 To Shin Box Step Through. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'step_up', '90 To 90 To Shin Box Step Through', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7916d4a0-9344-45ae-90f7-59815241b016', 'Seated Shoulder Press (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Seated Shoulder Press, an effective shoulder pressing exercise. The triceps assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '4051201', '04051201-Dumbbell-Seated-Shoulder-Press_Shoulders-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Shoulder Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 94, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('791fb835-d25f-4905-8705-be4ee78be419', 'Extended Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '94951201', '94951201-Suspender-Extended-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Extended Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Extended Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('7929bed9-63ad-449d-939b-ab2494531438', 'Safety Bar Front Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '42181201', '42181201-Safety-Bar-Front-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'front_squat', 'Safety Bar Front Squat', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('792aa1ce-1c3a-4eff-8804-a7a29d5649b2', 'Standing Scapular External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build stronger shoulders with this rotation movement focusing on your rotator cuff. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '83421201', '83421201-Bodyweight-Standing-Scapular-External-Rotation-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Bodyweight Standing Scapular External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'external_rotation', 'Standing Scapular External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7934f5d7-3097-44e8-bb95-89ea1ab9602d', 'Standing Wall Slide Squat (Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Standing Wall Slide Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Leg training boosts metabolism and builds functional, real-world strength.', '84361201', '84361201-Standing-Wall-Slide-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand with feet about shoulder-width apart. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 79, 7, 8, TRUE, TRUE, 'serratus', 'Standing Wall Slide Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('79391e88-ff1a-46f2-881d-3d6d21f9ce97', 'Incline Bicep Curl (Cable)', 'Arms', 'Cables, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Incline Inner Biceps Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Using an incline changes the angle of resistance for varied muscle recruitment. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '79311201', '79311201-Cable-Incline-Inner-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Inner Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 93, 5, 7, FALSE, TRUE, 'bicep_curl', 'Incline Inner Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('79398236-3763-48c3-85b1-c8a0a623f22e', 'Side Lying Leg Adduction', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Side Lying Leg Adduction is a lower body movement exercise that targets your adductors. You''ll also feel your glutes working to support the movement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '58361201', '58361201-Bodyweight-Side-Lying-Leg-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Bodyweight Side Lying Leg Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Side Lying Leg Adduction', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('793bb346-6455-4c02-8193-b8bea9b2ba4c', 'Single Straight Leg Glute Bridge Hold', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Single Straight Leg Glute Bridge Hold is a hip-dominant bridging exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '51981201', '51981201-Single-Straight-Leg-Glute-Bridge-Hold-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Hold the position for the prescribed time, maintaining tension. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Single Straight Leg Glute Bridge Hold', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('79428695-ec74-4b85-af49-7a194308a53d', 'Bicep Curl (Smith Machine)', 'Arms', 'Smith Machine', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Smith Biceps Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. Machine exercises are great for isolating muscles and training to failure safely. Arm strength supports grip, pulling, and pushing in compound movements.', '70781201', '70781201-Smith-Bicep-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'bicep_curl', 'Smith Biceps Curl', 'Biceps Curl', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('7959411e-6274-43e4-b631-199a59a9411a', 'Knee Drive', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. This is a great exercise for all fitness levels with proper scaling.', '50841201', '50841201-Knee-Drive-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Set up in the starting position for Knee Drive. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('796d9dac-e883-4f05-9d30-f5ae1e314486', 'Leg Raise (Kettlebell)', 'Core', 'Kettlebell', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kettlebell Leg Raise is a core raising exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The kettlebell grip position adds a unique training stimulus. Core strength is foundational for athletic performance and injury prevention.', '74671201', '74671201-Kettlebell-Leg-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriately weighted kettlebell for Kettlebell Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise', 'crunch, plank, v_up', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('797b76a3-c606-4661-a3da-91383a600cfe', 'Standing Military Press - Without Rack (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Secondary activation of your triceps provides additional muscle engagement. The standing position engages your core for stability. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '11651201', '11651201-Barbell-Standing-Military-Press-(without-rack)_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Standing Military Press. 2. Stand with feet about shoulder-width apart. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', NULL, 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 91, 7, 9, TRUE, FALSE, 'shoulder_press', 'Standing Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('7982b41b-3e8a-4eea-b107-0524f6056756', 'Mountain Climber Cross Kick', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. Your shoulders, core work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '90481201', '90481201-Mountain-Climber-Cross-Kick-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Cross Kick', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('798fb604-1a5e-484d-9332-f903b4ed2d7f', 'Seated Triceps Extension (Machine)', 'Arms', 'Tricep Extension Machine', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Lever Seated Triceps Extension (plate Loaded) targets your triceps through a extension motion. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Arm strength supports grip, pulling, and pushing in compound movements.', '88491201', '88491201-Lever-Seated-Triceps-Extension-(plate-loaded)-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lever Seated Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('79b7d429-269f-4a94-9a44-380fedda9e4c', 'Side Step Upright Row (Step Platform)', 'Shoulders', 'Step Platform', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build power and athleticism with this high-intensity rowing exercise that challenges your entire body. Secondary activation of your traps provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '66661201', '66661201-Side-Step-Upright-Row-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'upright_row', 'Side Step Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('79c15e54-8101-451d-86fb-c4a4d9cd2f92', 'Goblet Glute Dominant Bulgarian Split Sq (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Dumbbell Goblet Glute Dominant Bulgarian Split Sq is a movement exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '106591201', '106591201-Dumbbell-Goblet-Glute-Dominant-Bulgarian-Split-Sq.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Glute Dominant Bulgarian Split Sq. 2. Set up in the starting position for Dumbbell Goblet Glute Dominant Bulgarian Split Sq. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'split_squat', 'Goblet Glute Dominant Bulgarian Split Sq', 'split_squat, lunge, leg_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('79c48805-3f5d-40bd-8647-82403e5bf983', 'Lateral Shuffle Squat Tap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '69081201', '69081201-Lateral-Shuffle-Squat-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'shuffle', 'Lateral Shuffle Squat Tap', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('79d6522d-8924-48b7-a5b8-b82285c9a44a', 'Weighted Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '74211201', '74211201-Weighted-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Raise the weight in front of you to shoulder height. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'front_raise', 'Weighted Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('79dff7b8-b7ed-4977-8cdb-7c5eb41519e0', 'Over Bench Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'The Dumbbell Over Bench Wrist Curl strengthens your forearms and grip through a curling motion. Your forearms work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '26311201', '26311201-Dumbbell-Over-Bench-Wrist-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Over Bench Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Maintain a neutral spine throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Over Bench Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('79e7d49c-f9ef-486f-b267-f0045d976b5c', 'Seated Rotating Boxing Rolls (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Rotating Boxing Rolls On A Chair is an explosive exercise that combines cardiovascular training with dynamic movement movements. Being seated provides stability, allowing you to focus on the working muscles. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '86341201', '86341201-Seated-Rotating-Boxing-Rolls-on-a-Chair-(male)_Ply.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up a box or step platform at the appropriate height. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 29, 7, 8, TRUE, TRUE, 'boxing', 'Seated Rotating Boxing Rolls On A Chair', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('79e9d022-cc63-4d70-a60c-e59ca4aeb584', 'Weighted Flutter Kicks', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this kicking movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '104281201', '104281201-Weighted-Flutter-Kicks_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Weighted Flutter Kicks. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Weighted Flutter Kicks', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('79ed4981-b83b-4b55-8af0-262ee6846d2b', 'Jump Squat II', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Jump Squat II is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '5131201', '05131201-Jump-Squat-II_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Explode upward from the bottom, jumping as high as possible. 4. Land softly with bent knees and immediately descend into the next rep. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat_jump', 'Jump Squat II', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('79fc42a1-8e41-475d-8ccb-ff8e8681f3a2', 'Donkey Kick - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '74311201', '74311201-Alternate-Donkey-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Donkey Kick. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_kickback', 'Donkey Kick - Alternating', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a09bac9-a29e-418f-be01-74869c9e9fd8', 'Lying Crossed Legs Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Lying Crossed Legs Twist. You''ll also feel your abs working to support the movement. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '79191201', '79191201-Lying-Crossed-Legs-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Crossed Legs Twist. 2. Rotate your torso through the movement pattern for Lying Crossed Legs Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Lying Crossed Legs Twist', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7a135ad7-c3f0-4900-b05d-4b6d2365a3f5', 'Seated Switching Palm Row (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '91141201', '91141201-Sitting-Switching-Palm-Row-on-a-Chair-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout. Beneficial for overall back development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Switching Palm Row On A Chair', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a1c2d70-4341-48b8-a663-5d2db2402110', 'Seated Concentration Curl - Close Grip (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Barbell Seated Close Grip Concentration Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. The seated position helps isolate the target muscles by removing momentum. Using a barbell provides stability for progressive overload. Dedicated arm training builds both strength and muscular definition.', '891201', '00891201-Barbell-Seated-Close-grip-Concentration-Curl_Upper.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Close Grip Concentration Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'concentration_curl', 'Seated Concentration Curl - Close Grip', 'Seated Concentration Curl - Close Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('7a248673-a954-4bca-a19e-6975f6b2c59c', 'Palm Up Palm Down Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your delts with the Palm Up Palm Down Rotation, an effective shoulder rotation exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '46661201', '46661201-Palm-up---Palm-down-Rotation-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Rotate your torso through the movement pattern for Palm Up Palm Down Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Palm Up Palm Down Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a2fec52-f1e7-4d3e-a9b0-3d76f6120493', 'Seated Wrist Flexors Stretch', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Seated Wrist Flexors Stretch is a flexibility exercise that targets your wrists, helping to release tension and improve range of motion. Secondary activation of your forearms provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '82441201', '82441201-Seated-Wrist-Flexors-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Wrist Flexors Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'wrist_stretch', 'Seated Wrist Flexors Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7a41daf2-8882-4d25-842a-4290e4b0463f', 'Side Bend Plank', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Work your side abdominals with this stabilization exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '80931201', '80931201-Side-Bend-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. This exercise is excellent for obliques development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_bend', 'Side Bend Plank', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('7a561bbe-ed1f-4de2-ac30-441a30aa373b', 'Belt Sumo Squat (Machine)', 'Legs', 'Lever Machine', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness. Progress gradually by increasing resistance over time. Consistency with this movement will yield noticeable results.', '94931201', '94931201-Lever-Belt-Sumo-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Belt Sumo Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Lever Belt Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('7a5bb663-cd83-4354-a41e-24d35a692b42', 'Seated Shoulders Press - Neutral Grip (Band)', 'Shoulders', 'Resistance Band', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Band Seated Neutral Grip Shoulders Press is a pressing exercise that targets your delts for shoulder development. Being seated provides stability, allowing you to focus on the working muscles. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '68741201', '68741201-Band-Seated-Neutral-Grip-Shoulders-Press_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Secure the resistance band appropriately for Band Seated Neutral Grip Shoulders Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. Start with the weight at shoulder level. 5. Press directly overhead until your arms are fully extended. 6. Lower back to shoulder level with control. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulders Press - Neutral Grip', 'Seated Shoulders Press - Neutral Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7a5ccaaf-cd21-4cbe-8f22-1ef1fd71af96', 'Serratus Push In Side Plank Position', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '92051201', '92051201-Serratus-Push-in-Side-Plank-Position-(female)_Ches.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Serratus Push In Side Plank Position', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a6198ed-1a80-4652-8275-4e913cfbb110', 'Single Arm Starfish Crunch (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '54681201', '54681201-Dumbbell-Single-Arm-Starfish-Crunch-(beginner)-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'crunch', 'Single Arm Starfish Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7a74b4cb-0732-49f4-aa5f-7e0f5b244704', 'Swing Clean Grip Front Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads","Glutes","Core"}'::text[], '{}'::text[], 'This full-body squatting exercise challenges multiple muscle groups simultaneously. You''ll also feel your glutes, core working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Compound movements like this develop coordination, power, and overall fitness.', '77511201', '77511201-Kettlebell-Swing-Clean-grip-Front-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Swing Clean Grip Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'front_squat', 'Swing Clean Grip Front Squat', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7a78a2dc-fa89-4052-bff4-5fb6576a2f9d', 'Air Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '39481201', '39481201-Air-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Air Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a79fe9c-a2c4-4b41-bbd7-1b7f1d4c5426', 'Weighted Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements. This is a great exercise for all fitness levels with proper scaling.', '107071201', '107071201-Weighted-Pull-Up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Weighted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a7a360e-4cd1-4868-8a06-520c4eab9c35', 'Drag Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition. Start with lighter weight to master the movement pattern.', '59241201', '59241201-Dumbbell-Drag-Curl-(VERSION-2)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Drag Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Drag Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7a7ce3ce-5fec-47a1-97a2-ceca1ce67836', 'Downward Dog Sprint', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Hamstrings","Shoulders"}'::text[], 'The Downward Dog Sprint is an explosive exercise that combines cardiovascular training with dynamic movement movements. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '56121201', '56121201-Downward-Dog-Sprint-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Downward Dog Sprint. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Downward Dog Sprint', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7a8733b6-20b4-4fe0-9ce5-828997db551c', 'Standing Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Secondary activation of your abs provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '48101201', '48101201-Standing-Side-Bend-(VERSION-2)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Stretch', 52, 7, 8, TRUE, TRUE, 'side_bend', 'Standing Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a885ea7-aaf2-4077-87c0-6e8499981fda', 'Chest Fly And Press Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '76371201', '76371201-Chest-Fly-and-Press-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly And Press Up', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7a8b5151-7d1b-4e62-8149-63b09b781717', 'Seated Single Arm Chest Press (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Cable Seated Single Arm Chest Press, an effective pressing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '90131201', '90131201-Cable-Seated-Single-Arm-Chest-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Single Arm Chest Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'bench_press', 'Seated Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('7a94afdc-3324-45db-8953-c93f8c5add24', 'Heel Touch Side Kick Squat - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Alternate Heel Touch Side Kick Squat is a lower body squatting exercise that targets your obliques. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '70971201', '70971201-Alternate-Heel-Touch-Side-Kick-Squat-(female)_Thig.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Heel Touch Side Kick Squat - Alternating', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7a9f15dd-53eb-4127-8161-fd25bd25301c', 'Posterior Chain Flexibility Test', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Posterior Chain Flexibility Test provides a deep stretch for your full body, ideal for recovery and mobility work. Include this in your routine for better mobility and reduced muscle tension.', '67931201', '67931201-Posterior-Chain-Flexibility-Test-(female)_Stretchi.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Move into the stretch position for Posterior Chain Flexibility Test. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Posterior Chain Flexibility Test', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7aa531bb-4dda-4a6a-803a-cecb5c9dd5cf', 'Lateral Tap In Squat Position', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Can be modified for beginners or progressed for advanced athletes.', '73581201', '73581201-Lateral-Tap-in-Squat-Position-(front-POV)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Lateral Tap In Squat Position', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7aafb864-b345-4834-8f94-38180cb25692', 'Swing Torso Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Swing Torso Twist builds reactive power and improves conditioning. You''ll also feel your abs working to support the movement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '74831201', '74831201-Swing-Torso-Twist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Rotate your torso through the movement pattern for Swing Torso Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Swing Torso Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7ab4128a-af10-4385-9ef8-b616a45fc9f5', 'Supinated Grip Pull Apart (Resistance Band)', 'Arms', 'Resistance Band, Anchor Point', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this pulling exercise. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '100291201', '100291201-Resistance-Band-Supinated-grip-Pull-Apart-(female.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Supinated Grip Pull Apart. 2. Use an underhand (supinated) grip with palms facing up/toward you. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pull_apart', 'Supinated Grip Pull Apart', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7ab41f96-1357-49c5-a1c3-eb2c0e95d2bd', 'Pendulum Arms Side Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '66631201', '66631201-Pendulum-Arms-Side-Leg-Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Pendulum Arms Side Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7ab6f4b6-e63c-4703-8579-682f29f15e98', 'Stack Seated Incline Single Arm Chest Press (Machine)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '106701201', '106701201-Lever-Stack-Seated-Incline-Single-Arm-Chest-Press.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Stack Seated Incline Single Arm Chest Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Stack Seated Incline Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('7ab99d81-8992-4476-b447-5710c162bd7b', 'Seated Calf Raise (Barbell)', 'Legs', 'Barbell, Flat Bench', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The seated position helps isolate the target muscles by removing momentum. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '26761201', '26761201-Barbell-Seated-Calf-Raise-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Calf Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', 'Push', 'Push', 'Compound', 'Unilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Overhand', 'Standard', 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'calf_raise', 'Seated Calf Raise', 'calf_raise, standing_calf_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('7abdbb50-2614-4a2e-b88c-a04fa1d056cc', 'Seated Opposite Touch (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '76291201', '76291201-Sitting-Opposite-Touch-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Opposite Touch On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ac51e73-74fa-48df-af72-ebbbd65c4cab', 'Lying Knee Hugs', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Knee Hugs is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Performing this lying down removes momentum for stricter form. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '78411201', '78411201-Lying-Knee-Hugs-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Knee Hugs. 2. Move into the stretch position for Lying Knee Hugs. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Knee Hugs', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ac69595-95b1-4561-a1d1-e96fe7e98038', 'Frog Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '62821201', '62821201-Frog-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Frog Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ac6eef4-1ac0-4977-895a-fb9532f78056', 'Lying Elbow To Knee', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. Start with lighter weight to master the movement pattern.', '23121201', '23121201-Lying-Elbow-to-Knee_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Lie down in the appropriate position for Lying Elbow To Knee. 2. Set up in the starting position for Lying Elbow To Knee. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Elbow To Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ae6b643-7c0f-41e6-b57a-3601038b553e', 'Standing Wide Legged Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Target your hamstrings with this stretching stretch that helps restore range of motion. Your lower back work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '97701201', '97701201-Standing-Wide-Legged-Hamstring-Stretch-(female)_St.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Wide Legged Hamstring Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Standing Wide Legged Hamstring Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('7ae9034f-4226-451d-8a9d-552075b474c2', 'Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '7871201', '07871201-Squat-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b03034e-6536-4c3b-a561-59e74b2ae6da', 'Jack Knife Pike (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Suspension training adds instability, increasing core activation throughout. Core strength is foundational for athletic performance and injury prevention.', '10811201', '10811201-Suspender-Jack-knife-Pike-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Jack Knife Pike. 2. Set up in the starting position for Suspender Jack Knife Pike. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 40, 9, 8, TRUE, TRUE, 'general_exercise', 'Suspender Jack Knife Pike', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 60, 4, 68, 85, 85, 70),
('7b0b6c7c-fb20-4703-aa20-62a0d431db43', 'Standing Torso Rotation (Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this rotation exercise that strengthens your obliques. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '99581201', '99581201-Band-Standing-Torso-Rotation-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Standing Torso Rotation. 2. Begin in a standing position with good posture. 3. Rotate your torso through the movement pattern for Band Standing Torso Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Torso Rotation', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7b131b28-ab94-42d4-8514-3703dc894ae9', 'Inverted Row On Bench', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Inverted Row On Bench is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps working to support the movement. A strong back improves posture, prevents injury, and balances pressing movements.', '22981201', '22981201-Inverted-Row-on-Bench_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row On Bench', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b22bae5-98d7-4578-ad51-16a617966fac', 'Glute Bridge - Hands On Bar (Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Barbell Glute Bridge (hands On Bar) is a hip-dominant bridging exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '29651201', '29651201-Barbell-Glute-Bridge-(hands-on-bar)-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Glute Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge', 'hip_thrust, romanian_deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('7b23ebd4-38cf-4d63-92ed-a1b1729378eb', 'Forward Kick - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Alternate Forward Kick is an explosive exercise that combines cardiovascular training with dynamic kicking movements. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '89851201', '89851201-Alternate-Forward-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Forward Kick. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Forward Kick - Alternating', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b346ce6-b707-486b-aa2f-3dbfca9060a0', 'Walking Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '42951201', '42951201-Dumbbell-Walking-Lunge-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Walking Lunge. 2. Step forward into a lunge, then bring your back foot forward for the next step. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 82, 9, 8, FALSE, TRUE, 'lunge', 'Walking Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', TRUE, 1, 60, 4, 92, 90, 92, 90),
('7b39e46f-df25-41a7-995f-6f7d03e42f00', 'Standing Elbow Together Scoop', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Elbow Together Scoop is an arm movement exercise targeting your full body. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Arm strength supports grip, pulling, and pushing in compound movements.', '85581201', '85581201-Standing-Elbow-Together-Scoop-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Elbow Together Scoop. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Elbow Together Scoop', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b3a1cf4-b0cf-4a58-a982-6db336ce047a', 'Lying Swimming Legs', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts. Maintain proper breathing - exhale during the effort phase.', '58341201', '58341201-Lying-Swimming-Legs-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Swimming Legs. 2. Set up in the starting position for Lying Swimming Legs. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'swimming', 'Lying Swimming Legs', 'squat, lunge, leg_press', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('7b53d0b2-c1d3-4e45-82f0-0e408aecbe2b', 'Serratus Wall Slide (Wall)', 'Shoulders', 'Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Serratus Wall Slide is a movement exercise that develops back strength and muscle. Secondary activation of your upper back provides additional muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '50251201', '50251201-Serratus-Wall-Slide_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Serratus Wall Slide. 3. Execute the movement with proper form, focusing on your rotator cuff. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'serratus', 'Serratus Wall Slide', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b5d851f-ee2e-40de-a008-2ded2dfc525a', 'Seated Scapular Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this rotation movement targeting your core. Being seated provides stability, allowing you to focus on the working muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '81181201', '81181201-Seated-Scapular-Rotation-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Scapular Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Scapular Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b5f99f6-8933-4c36-82ab-7399226cd366', 'Single Arm Floor Press (Kettlebell)', 'Chest', 'Kettlebell', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The kettlebell grip position adds a unique training stimulus. A well-developed chest contributes to upper body strength and aesthetics.', '12981201', '12981201-Kettlebell-One-Arm-Floor-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Floor Press. 2. Position yourself on the floor for Kettlebell One Arm Floor Press. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'bench_press', 'Single Arm Floor Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7b6c9464-4a1d-426e-95a3-70a5bcb96a0d', 'Seated Pull Up - Legs Elevated (Pull-Up Bar)', 'Back', 'Pull-Up Bar, Step Platform', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Back development is crucial for pulling strength and overall upper body function.', '47831201', '47831201-Seated-Pull-up-(legs-elevated)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'pull_up', 'Seated Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b6ddc70-ad90-4473-908b-a26b8040528d', 'Table Top Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'The Table Top Stretch On Chair provides a deep stretch for your full body, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105061201', '105061201-Table-Top-Stretch-on-Chair-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Move into the stretch position for Table Top Stretch On Chair. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Table Top Stretch On Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7b7283c0-64e3-498c-b35e-44781a703d17', 'Bridge Pose', 'Full Body', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. You''ll also feel your glutes, chest, shoulders working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '79551201', '79551201-Bridge-Pose-(VERSION-2)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Bridge Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7b7d19c6-8579-4302-9d9e-e58db29d4628', 'Balance Board', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '106861201', '106861201-Balance-Board-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Balance Board. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'balance', 'Balance Board', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7b856e7a-c0f6-40a2-8af0-57ee1f9ce66c', 'Side Shuffle Leg Side Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning. Can be modified for beginners or progressed for advanced athletes.', '64821201', '64821201-Side-Shuffle-Leg-Side-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Set up in the starting position for Side Shuffle Leg Side Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Side Shuffle Leg Side Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('7b89b6c6-55f5-4b88-869b-d052bcc17f8d', 'Glute Ham Raise', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This raising exercise isolates your glutes for improved hip strength and power. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '57771201', '57771201-Glute-Ham-Raise-(VERSION-2)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Raise the weight in the prescribed direction for Glute Ham Raise. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_exercise', 'Glute Ham Raise', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7b8d426c-784c-4c32-a54c-cff38e5163fa', 'Middle Back Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretching exercise engages your abs for improved core stability and strength. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts. Perfect for including in both strength and hypertrophy programs.', '42881201', '42881201-Middle-Back-Stretch-(male)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up in the starting position for Middle Back Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Middle Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7b917760-d05c-466a-8e4e-02a901b7a3ed', 'Pass Through (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. Resistance bands provide accommodating resistance that increases through the range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '83651201', '83651201-Resistance-Band-Pass-Through_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Secure the resistance band appropriately for Resistance Band Pass Through. 2. Set up in the starting position for Resistance Band Pass Through. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pass_through', 'Pass Through', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7b9c98f2-7e29-48b8-930f-3c96bbac2ac2', 'Mountain Climber Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The hip flexors, shoulders assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '58411201', '58411201-Mountain-Climber-Lunge-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('7ba6d9cd-bef0-45ea-bb16-ed62c1b09819', 'Stepback With Hands Raise', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'Elevate your training with this raising exercise that develops speed, power, and coordination. The quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '46391201', '46391201-Stepback-with-Hands-Raise-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Stepback With Hands Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Stepback With Hands Raise', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7baad776-b567-4fdd-bb7d-ad55c0693120', 'Standing Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'The Dumbbell Standing Wrist Curl strengthens your forearms and grip through a curling motion. You''ll also feel your forearms working to support the movement. The standing position engages your core for stability. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '54621201', '54621201-Dumbbell-Standing-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Wrist Curl. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'wrist_curl', 'Standing Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7babba2e-d444-451b-af4f-48370f26e2f7', 'Butt Kick with Row', 'Back', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build power and athleticism with this high-intensity rowing exercise that challenges your entire body. Secondary activation of your hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '55441201', '55441201-Butt-Kick-with-Row-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. Great for building strength in your upper back.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_kickback', 'Butt Kick With Row', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7bb650af-38bd-4f30-a161-837f5a91403f', 'Arm Crossover Chest Out', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '53571201', '53571201-Arm-Crossover-Chest-Out-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Arm Crossover Chest Out. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', 'Push', NULL, 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Crossover Chest Out', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7bc43727-8362-4f06-829b-4f76d27c3e8b', 'Glute Bridge Two Legs On Bench', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Two Legs On Bench is a hip-dominant bridging exercise that targets your glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. Strong legs are the foundation for athletic performance and functional fitness.', '35231201', '35231201-Glute-Bridge-Two-Legs-on-Bench-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Two Legs On Bench', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7bda014a-5c62-4c48-adc4-03be135c5a39', 'Stiff Leg Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'This hip hinge exercise engages your abs for improved core stability and strength. You''ll also feel your glutes, lower back working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Core strength is foundational for athletic performance and injury prevention.', '26361201', '26361201-Dumbbell-Stiff-Leg-Deadlift-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Stiff Leg Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Stiff Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('7be40f08-948c-4005-8470-50145fc567c1', 'Standing Single Leg Hip Swirl Support (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop functional strength with the Standing Single Leg Hip Swirl With Chair Support, a comprehensive movement exercise. Performing this standing challenges your balance and core engagement. Full body exercises are time-efficient and build functional, real-world strength.', '105171201', '105171201-Standing-Single-Leg-Hip-Swirl-with-Chair-Support_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Stand tall with your feet firmly planted. 3. Complete all reps on one side, then switch to the other side. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 32, 7, 8, TRUE, TRUE, 'leg_exercise', 'Standing Single Leg Hip Swirl With Chair Support', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7bef1049-c8b8-4f18-b2e5-f9aafbd30b30', 'Crossed Arms Front Leg Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '56841201', '56841201-Crossed-Arms-Front-Leg-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up in the starting position for Crossed Arms Front Leg Kick. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Crossed Arms Front Leg Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7bff978d-20e4-44ae-91d0-ae826b2b76fd', 'Overhead Forward Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Overhead Forward Lunge is a lunging exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '96111201', '96111201-Bodyweight-Overhead-Forward-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Overhead Forward Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7c039315-8391-4094-a8cb-fbc842f967bd', 'Triceps Extension (Cable) - Alternating', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition. Focus on controlled form throughout each repetition.', '105861201', '105861201-Cable-Alternate-Triceps-Extension-(female)_Upper-.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Alternate Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Triceps Extension - Alternating', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('7c06e945-d66c-473b-a574-c4e2ea0fbcdf', 'Lying Hip Leg Raise (On Floor)', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '6171201', '06171201-Lying-Hip-Leg-Raise-(on-floor)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Position yourself on the floor for Lying Hip Leg Raise. 2. Lie down in the appropriate position for Lying Hip Leg Raise. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Hip Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7c152950-1799-4242-b99b-1c163ca2e24f', 'Standing Forward Bend Uttanasana', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your hamstrings with this movement stretch that helps restore range of motion. Your lower back, calves work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '9591201', '09591201-Standing-Forward-Bend-Uttanasana-(female)_Stretchi.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Forward Bend Uttanasana. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Standing Forward Bend Uttanasana', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('7c191c05-77fe-4e30-8b7b-bab272f6b934', 'Single Leg Hip Thrust (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'The Dumbbell Single Leg Hip Thrust is a hip-dominant thrusting exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '80751201', '80751201-Dumbbell-Single-Leg-Hip-Thrust_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'hip_thrust', 'Single Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('7c1b25d2-d218-4a90-bd2b-7765ccc09412', 'Gate Openers', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Gate Openers builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '80651201', '80651201-Gate-Openers-(beginner)-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Set up in the starting position for Gate Openers. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Gate Openers', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7c1c1e6d-cff5-487d-a0e7-26f94d54cd67', 'Straight Arm Side Plank', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '80261201', '80261201-Straight-Arm-Side-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Straight Arm Side Plank', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('7c30afd6-a904-4eae-91b6-1d383040c658', 'Knee Raise Side Jab', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Knee Raise Side Jab builds reactive power and improves conditioning. The shoulders, core assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '59321201', '59321201-Knee-Raise-Side-Jab-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Knee Raise Side Jab', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7c4634d4-7752-4bff-9682-cd61c972f8b0', 'Squat To Side To Front Leg', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Bodyweight Squat To Side To Front Leg builds reactive power and improves conditioning. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '45071201', '45071201-Bodyweight-Squat-to-Side-to-Front-Leg_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Ideal for quads strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat To Side To Front Leg', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7c4ba370-66d6-4cf9-a7e6-ace2ce6ed1cc', 'Slow Motion Sprinter', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'The Slow Motion Sprinter is an explosive exercise that combines cardiovascular training with dynamic movement movements. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '72701201', '72701201-Slow-Motion-Sprinter-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Use a slow, controlled tempo throughout the entire range of motion. 2. Set up in the starting position for Slow Motion Sprinter. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'sprint', 'Slow Motion Sprinter', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7c50f5c6-d28a-4bfb-811e-e61b29b6b958', 'Side Hip Abduction (Machine)', 'Legs', 'Hip Abduction Machine', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Lever Side Hip Abduction is a lower body movement exercise that targets your glute med/abductors. You''ll also feel your glutes working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '10341201', '10341201-Lever-Side-Hip-Abduction_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Side Hip Abduction. 2. Set up in the starting position for Lever Side Hip Abduction. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lever Side Hip Abduction', 'hip_adduction, glute_bridge, clamshell', TRUE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('7c617ef6-fb9f-4224-89a4-16414b462ceb', 'Triceps Pushdown - SZ Bar - Reverse Grip (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Upper Chest"}'::text[], 'The Cable Reverse Grip Triceps Pushdown (SZ Bar) targets your triceps through a pushing motion. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '71121201', '71121201-Cable-Reverse-Grip-Triceps-Pushdown-(SZ-bar)-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Grip Triceps Pushdown. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Triceps Pushdown - Reverse Grip', 'Triceps Pushdown - Reverse Grip', TRUE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('7c6a481c-e4f1-49a0-ab11-02994927eddc', 'Incline Single Arm Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts. Control the negative portion for maximum muscle engagement. Consistency with this movement will yield noticeable results.', '74231201', '74231201-Dumbbell-Incline-One-Arm-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'arm_exercise', 'Incline Single Arm Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('7c6fb370-c4dd-4897-8d08-51576f81b842', 'Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Kettlebells are excellent for building functional, real-world strength. Lower body strength improves everything from walking to heavy compound lifts.', '106731201', '106731201-Kettlebell-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Select an appropriately weighted kettlebell for Kettlebell Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7c760daf-f0e3-4f74-b4b9-51f7c32d9a3e', 'Seated Twist (Band)', 'Core', 'Resistance Band', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Core strength is foundational for athletic performance and injury prevention.', '105711201', '105711201-Band-Seated-Twist_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Secure the resistance band appropriately for Band Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Band Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('7c83f84a-30b2-4e33-991b-072b4a19ba35', 'Good Morning Side Leg Lift', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Strengthen the back of your thighs with this movement exercise. You''ll also feel your glutes, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '74901201', '74901201-Good-Morning-Side-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Set up in the starting position for Good Morning Side Leg Lift. 2. Execute the movement with proper form, focusing on your hamstrings. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Good Morning Side Leg Lift', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7c867070-bb0e-47f1-a367-6fc0d631d28d', 'Bent Over Row - Underhand (Barbell)', 'Back', 'Barbell', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, lats work as secondary movers, adding to the training stimulus. Bending over allows gravity to provide resistance in a different plane. The barbell allows you to handle heavier loads for maximum strength gains. Back development is crucial for pulling strength and overall upper body function.', '1181201', '01181201-Barbell-Underhand-Bent-Over-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Grip a barbell with hands at the appropriate width for Barbell Underhand Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use an underhand (supinated) grip with palms facing up/toward you. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Underhand Bent Over Row', 'Bent Over Row - Underhand', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('7c87af80-4d57-4dca-a6c2-6cb0609301e2', 'Internal Rotation (TRX)', 'Shoulders', 'TRX', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'This rotation exercise focuses on your pectorals for improved chest strength and development. Suspension training adds instability, increasing core activation throughout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '75061201', '75061201-Suspender-Internal-Rotation_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Internal Rotation. 2. Rotate your torso through the movement pattern for Suspender Internal Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'external_rotation', 'Suspender Internal Rotation', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('7c9aaa57-8cab-48eb-8e5a-0ee834aeab7a', 'Side Step Boxing Handroll', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. You''ll also feel your quads working to support the movement. Great for improving athletic performance, burning calories, and building conditioning. Can be modified for beginners or progressed for advanced athletes.', '57711201', '57711201-Side-Step-Boxing-Handroll-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Boxing Handroll. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Boxing Handroll', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ca57bed-2341-4202-9fc2-9ecc22c282aa', 'Lying Floor 6 Inch Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '94511201', '94511201-Lying-Floor-6-Inch-Hold-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Position yourself on the floor for Lying Floor 6 Inch Hold. 2. Lie down in the appropriate position for Lying Floor 6 Inch Hold. 3. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Floor 6 Inch Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('7caf3d80-4a15-465e-9b0c-ea496612a698', 'Hanging Oblique Knee Raise On Parallel Bars (Pull-Up Bar)', 'Core', 'Pull-Up Bar, Dip Bars', '{"Obliques"}'::text[], '{"Abs","Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Hanging adds a grip and core stability component to the exercise. Core strength is foundational for athletic performance and injury prevention.', '79801201', '79801201-Hanging-Oblique-Knee-Raise-on-Parallel-Bars_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Raise the weight in the prescribed direction for Hanging Oblique Knee Raise On Parallel Bars. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'dip', 'Hanging Oblique Knee Raise On Parallel Bars', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7cb8b1cb-7ccd-405e-a3e7-2a32cbd7dd0a', 'Wall Sit From Deficit (Step Platform)', 'Legs', 'Step Platform, Wall', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'This movement movement emphasizes your quadriceps for stronger, more powerful legs. The glutes assist throughout the movement, making this a well-rounded exercise. Strong legs are the foundation for athletic performance and functional fitness.', '75581201', '75581201-Wall-sit-from-Deficit-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Wall Sit From Deficit. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'wall_sit', 'Wall Sit From Deficit', 'squat, leg_press, lunge', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('7cb8dda5-cd4c-4643-aa2a-cac972e89e7a', 'Side Bridge Hip Abduction (star)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Your glutes work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '7031201', '07031201-Side-Bridge-Hip-Abduction-(star)-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. Works well for glutes activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Bridge Hip Abduction', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7cbb74d8-2d63-4222-9138-d9f3ebb2a181', 'Rope Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '13231201', '13231201-Cable-Rope-Seated-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Adjust the cable machine to the correct height and attachment for Cable Rope Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Rope Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('7cc4d982-cd2b-476a-a231-5d9d730341fd', 'Lizard Lunge (advanced)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Lizard Lunge (advanced) helps improve mobility and prevent stiffness. You''ll also feel your glutes, hamstrings working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '80721201', '80721201-Lizard-Lunge-(advanced)-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Lizard Lunge. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_stretch', 'Lizard Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7cd36faa-085a-4db1-a239-e7c9a8259548', 'Rotary Calf (Machine)', 'Legs', 'Calf Raise Machine', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted movement exercise. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '23151201', '23151201-Lever-Rotary-Calf_Calves.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Rotary Calf. 2. Set up in the starting position for Lever Rotary Calf. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Rotary Calf', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('7cdcb699-6bb9-4c98-bb38-e4f912c36fcd', 'Forward Backward Lunge (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Lower body strength improves everything from walking to heavy compound lifts.', '86431201', '86431201-Kettlebell-Forward-Backward-Lunge-(VERSION-2)-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select an appropriately weighted kettlebell for Kettlebell Forward Backward Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Forward Backward Lunge', 'split_squat, step_up, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7cde3430-22a5-40ff-b8f2-78ca8f44737d', 'Calf Raise (Smith Machine)', 'Legs', 'Smith Machine', '{Calves}'::text[], '{Soleus}'::text[], 'Build stronger calves with this targeted raising exercise. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '11641201', '11641201-Smith-Calf-Raise-(version-2)_Calves-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Calf Raise. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'calf_raise', 'Smith Calf Raise', 'Calf Raise', FALSE, 'barbell', FALSE, 3, 60, 2, 80, 75, 20, 88),
('7ce81809-f281-493f-b9eb-be4eb272a9fe', 'Snatch High Pull', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Build total body strength and coordination with this multi-joint pulling movement. The quads, shoulders assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '107001201', '107001201-Snatch-High-Pull-(female)_Weightlifting_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Explosively pull the weight from the floor/hang position. 2. As it rises, pull yourself under and catch it overhead with locked arms. 3. Stand to complete the lift. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'upright_row', 'Snatch High Pull', 'power_snatch, clean, overhead_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7cf3c2f6-bcce-49cf-a514-1821b650f6fc', 'Arm Rotation Knee Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this rotation exercise that strengthens your obliques. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '51391201', '51391201-Arm-Rotation-Knee-Lift-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Rotate your torso through the movement pattern for Arm Rotation Knee Lift. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Arm Rotation Knee Lift', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7cfe582d-fa38-40a9-851a-dc8edec2ae6e', 'Arm Swing Forward Heel Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Arm Swing Forward Heel Tap is an explosive exercise that combines cardiovascular training with dynamic swinging movements. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '89791201', '89791201-Arm-Swing-Forward-Heel-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control. Ideal for full body strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Arm Swing Forward Heel Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d062853-9940-4528-8751-9524b6030ea7', 'Pushdown - Rope (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing movement isolates your triceps for improved arm development. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements. Start with lighter weight to master the movement pattern.', '2001201', '02001201-Cable-Pushdown-(with-rope-attachment)_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Adjust the cable machine to the correct height and attachment for Cable Pushdown. 2. Set up in the starting position for Cable Pushdown. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('7d0e8a3a-a66c-4080-942e-56c4d27abcda', 'Seated Open Wings', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Open Wings is a movement exercise that develops back strength and muscle. Being seated provides stability, allowing you to focus on the working muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '87281201', '87281201-Seated-Open-Wings-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Open Wings. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'lateral_raise', 'Seated Open Wings', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d11aaf8-5ad9-480b-83a8-e300eeaae7fb', 'High Row - Narrow Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. A strong back improves posture, prevents injury, and balances pressing movements.', '100701201', '100701201-Band-Narrow-Grip-High-Row_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Narrow Grip High Row. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'close_grip_bench', 'High Row - Narrow Grip', 'High Row - Narrow Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7d14d03f-a726-43a6-bf05-1537d91c74db', 'Clock Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Clock Push Up, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '2581201', '02581201-Clock-Push-Up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Clock Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d3622ff-f0cd-4af8-a63d-a9789077b0c2', 'Seated Hamstring Stretch (Chair)', 'Legs', 'Gymnastic Rings, Chair', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Seated Hamstring Stretch On A Chair provides a deep stretch for your hamstrings, ideal for recovery and mobility work. Your lower back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '104621201', '104621201-Seated-Hamstring-Stretch-on-a-Chair-(male)_Stretc.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Hamstring Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Seated Hamstring Stretch On A Chair', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('7d41552e-bb38-4981-a0c0-1f2f33505e7f', 'Low Chest Press (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '58141201', '58141201-Cable-Low-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'bench_press', 'Low Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('7d49b9c5-0df5-446f-ae4d-ac053929d61f', 'Easy Pose (hands On Face)', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Easy Pose (hands On Face) provides a deep stretch for your full body, ideal for recovery and mobility work. Include this in your routine for better mobility and reduced muscle tension.', '81591201', '81591201-Easy-Pose-(hands-on-face)-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Easy Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'general_exercise', 'Easy Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7d5d630d-97bd-4ad7-9faa-45c20ff2d6df', 'Lying Seal Row On Rack (Barbell)', 'Back', 'Barbell, Flat Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. The barbell allows you to handle heavier loads for maximum strength gains. Back development is crucial for pulling strength and overall upper body function.', '87981201', '87981201-Barbell-Lying-Seal-Row-on-Rack_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Lying Seal Row On Rack. 2. Lie down in the appropriate position for Barbell Lying Seal Row On Rack. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Lying Seal Row On Rack', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('7d629135-8f8d-40f9-b48c-8cc354b61e7c', 'Ankle Touch - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Perfect for including in both strength and hypertrophy programs.', '56251201', '56251201-Alternating-Ankle-Touch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternating Ankle Touch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Ankle Touch - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d638758-3762-46f4-b6dd-b39f0e40513c', 'Single Arm Lateral Bent Over (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Biceps"}'::text[], 'Target your rhomboids and mid-traps with this movement movement. Your biceps work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '1911201', '01911201-Cable-One-Arm-Lateral-Bent-over.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Lateral Bent Over. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Complete all reps on one side, then switch to the other side. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'back_exercise', 'Single Arm Lateral Bent Over', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('7d654a0e-3a62-4be2-a234-474939bd9d6e', 'Lying Scissors Cross', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Scissors Cross is a lower body movement exercise that targets your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '62131201', '62131201-Lying-Scissors-Cross-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Scissors Cross. 2. Set up in the starting position for Lying Scissors Cross. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Lying Scissors Cross', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d6f6c57-4bb9-4f46-b7a4-455142918684', 'Double Jerk (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Kettlebell Double Jerk, an effective shoulder movement exercise. The kettlebell''s offset center of mass increases the stability challenge. Strong shoulders improve overhead strength and support nearly all upper body movements.', '5271201', '05271201-Kettlebell-Double-Jerk_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Position two kettlebells for Kettlebell Double Jerk. 2. Set up in the starting position for Kettlebell Double Jerk. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'jerk', 'Double Jerk', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7d74e75e-dc3e-4dcc-90a4-b9a9b604728b', 'Downward Punch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. Your shoulders work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '73701201', '73701201-Downward-Punch-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Set up in the starting position for Downward Punch. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Downward Punch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7d89b505-0c24-45bf-90d1-84120153545d', 'Seated Quads Stretch - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Seated Alternating Quads Stretch helps improve mobility and prevent stiffness. The hip flexors assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '94581201', '94581201-Sitting-Alternating-Quads-Stretch-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Alternating Quads Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Alternate between sides/arms/legs with each repetition. Engage your stabilizer muscles for better control. An effective movement for your stretching routine.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Quads Stretch - Alternating', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7d8a614c-82cd-4ac4-84c0-83bfae0a6dec', 'Bicycle Crunch (Band) - Alternating', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Band Bicycle Crunch, focusing on your abs. Your abs work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '70791201', '70791201-Band-Bicycle-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Bicycle Crunch. 2. Bring one knee toward chest while extending the other leg. 3. Rotate to bring opposite elbow toward the bent knee. 4. Alternate sides in a pedaling motion. 5. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', 'Trunk Flexion', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'cycling', 'Bicycle Crunch - Alternating', 'Alternating Bicycle Crunch', FALSE, 'bodyweight', FALSE, 3, 60, 2, 60, 85, 90, 50),
('7d8e5134-6d48-4639-abb2-c82faa192c58', 'Drag Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '97261201', '97261201-Dumbbell-Drag-Curl-(VERSION-2)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Drag Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Drag Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7d994778-f8c4-4c81-89cd-99dc208e92d5', 'Assisted Chin Up - From Knee (Band)', 'Back', 'Resistance Band, Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. Your biceps work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '100711201', '100711201-Band-Assisted-Chin-Up-(From-Knee)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Assisted Chin Up. 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Repeat for the prescribed number of repetitions.', 'Vertical Pull', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Hanging', NULL, 'Underhand (Supinated)', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7da1fdee-b505-4ced-8382-209327b25f47', 'Side Lying Hip Internal External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Side Lying Hip Internal External Rotation is a rotation exercise that targets your rotator cuff for shoulder development. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '84931201', '84931201-Side-Lying-Hip-Internal-External-Rotation-(female).mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Rotate your torso through the movement pattern for Side Lying Hip Internal External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Side Lying Hip Internal External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7da9b517-0d99-4ace-9897-eb4d0ac1c8b0', 'Seated Shoulder Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build a stronger back with this movement movement targeting your delts. Being seated provides stability, allowing you to focus on the working muscles. Back development is crucial for pulling strength and overall upper body function. Quality repetitions are more important than quantity.', '89371201', '89371201-Seated-Shoulder-Circle-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Shoulder Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulder Circle', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7db1b4cc-51d8-4abb-b343-39bc9049726a', 'Deadlift (Machine)', 'Back', 'Lever Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Lever Deadlift (plate Loaded) is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '30991201', '30991201-Lever-Deadlift-(plate-loaded)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'deadlift', 'Lever Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('7db8e8e8-6420-48a2-9ae9-d308b1fed445', 'Double Punch Front Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. You''ll also feel your shoulders working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '56871201', '56871201-Double-Punch-Front-Leg-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up in the starting position for Double Punch Front Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Double Punch Front Leg Lift', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7dc271a4-5d13-4320-8c71-5698945ebccb', 'Side To Side Step With Raise Hands', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'A challenging plyometric exercise, the Side To Side Step With Raise Hands builds reactive power and improves conditioning. Secondary activation of your quads provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '45501201', '45501201-Side-To-Side-Step-with-Raise-Hands_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'general_exercise', 'Side To Side Step With Raise Hands', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7dcce1a1-8188-4907-9e67-695654c6032b', 'Standing Opposite Straight Arm Clasp Raise (Left Over Right)', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Standing Opposite Straight Arm Clasp Raise (left O, a comprehensive raising exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '94601201', '94601201-Standing-Opposite-Straight-Arm-Clasp-Raise-(left-o.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Raise the weight in the prescribed direction for Standing Opposite Straight Arm Clasp Raise (left O. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'arm_exercise', 'Standing Opposite Straight Arm Clasp Raise (left O', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7dce220b-fbaf-4952-9c01-d8c508885374', 'Feet And Ankles Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretching movement focuses on your gastrocnemius and soleus. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '32471201', '32471201-Feet-and-Ankles-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Set up in the starting position for Feet And Ankles Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Feet And Ankles Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7dd0cf6f-fa83-44cd-b632-8a66814af74f', 'Lying Single Arm Supinated Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '25871201', '25871201-Dumbbell-Lying-One-Arm-Supinated-Triceps-Extension.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lie down in the appropriate position for Dumbbell Lying One Arm Supinated Triceps Extension. 3. Use an underhand (supinated) grip with palms facing up/toward you. 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Single Arm Supinated Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7dd3c1f7-8a74-4de9-85d1-e6d7de061042', 'Floating Run (Chair)', 'Full Body', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Great for improving athletic performance, burning calories, and building conditioning.', '66371201', '66371201-Floating-Run-on-Chair-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Floating Run On Chair. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'running', 'Floating Run On Chair', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7df7ed6f-b8a3-4c95-bd13-e32db2c67cfd', 'Single Arm High To Low Woodchopper (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Strengthen your midsection with this movement movement that works your full body. Cable resistance creates smooth, continuous muscle engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '84731201', '84731201-Cable-Single-Arm-High-to-Low-Woodchopper-(male)_Wa.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Complete all reps on one side, then switch to the other side. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'woodchop', 'Single Arm High To Low Woodchopper', 'russian_twist, pallof_press, cable_crunch', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('7df8d247-bfd6-44e9-a3ac-348aee382cb7', 'Seated Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '74091201', '74091201-Dumbbell-Seated-Hammer-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Hammer Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'hammer_curl', 'Seated Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7df9ff7a-7ab7-4b96-ab32-c76d4c1cfeb1', 'Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements. A staple exercise that belongs in most training programs.', '6521201', '06521201-Pull-up_Back-FIX3_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7dff146a-ee70-4a06-84f7-40c0932af16c', 'Leg Lift Twist - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'Elevate your training with this twisting exercise that develops speed, power, and coordination. You''ll also feel your abs working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '89061201', '89061201-Alternate-Leg-Lift-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Rotate your torso through the movement pattern for Alternate Leg Lift Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Leg Lift Twist - Alternating', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7e03c913-db7e-4987-aedc-ead2ce1a3990', 'Leg Over Head Calf Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. Maintain proper breathing - exhale during the effort phase. Consistency with this movement will yield noticeable results.', '64111201', '64111201-Leg-Over-Head-Calve-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Move into the stretch position for Leg Over Head Calve Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Leg Over Head Calf Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7e0842b5-5713-4102-b73e-6ee70aa94c96', 'Squat Mobility Complex', 'Legs', 'Bodyweight', '{"Shoulders"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat Mobility Complex is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '29891201', '29891201-Squat-mobility-Complex_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep the movement smooth and controlled. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 73, 2, 6, FALSE, TRUE, 'mobility', 'Squat Mobility Complex', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7e0c7bd7-7707-4dc8-bfd2-519c0ebea6ee', 'Seated Shoulder Press (Smith Machine)', 'Shoulders', 'Smith Machine', '{Deltoids}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Smith Seated Shoulder Press is a pressing exercise that targets your delts for shoulder development. Secondary activation of your triceps provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Shoulder development enhances both performance and upper body aesthetics.', '36201201', '36201201-Smith-Seated-Shoulder-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Seated Shoulder Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'shoulder_press', 'Smith Seated Shoulder Press', 'Seated Shoulder Press', FALSE, 'barbell', FALSE, 3, 90, 4, 80, 75, 20, 88),
('7e26ab7b-df56-4db6-9850-93be89c80910', 'Front Crossover Foot Tap', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. You''ll also feel your front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '77541201', '77541201-Front-Crossover-Foot-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Front Crossover Foot Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Front Crossover Foot Tap', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7e339a39-ebb1-4e97-9e73-1cc634db3080', 'Wrist Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build grip strength and forearm size with this pushing exercise. You''ll also feel your triceps, front delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '69451201', '69451201-Wrist-Push-up-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Wrist Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7e3968ae-a5b9-47b0-9cc6-6f2805b1576a', 'Lying Straight Arms Pullover (EZ Bar)', 'Chest', 'EZ Bar, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'The Ez Bar Lying Straight Arms Pullover is a pulling exercise that develops back strength and muscle. Your lats, triceps work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. A strong back improves posture, prevents injury, and balances pressing movements.', '98091201', '98091201-Ez-Bar-Lying-Straight-Arms-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Lie down in the appropriate position for Ez Bar Lying Straight Arms Pullover. 3. With arms slightly bent, lower the weight behind your head in an arc. 4. Pull the weight back over your chest, squeezing your lats and chest. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pullover', 'Ez Bar Lying Straight Arms Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('7e48b365-950a-4559-8748-9e837e006ac2', 'Wide Stance Anti Rotation Chop (Resistance Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Resistance Band Wide Stance Anti Rotation Chop, focusing on your core. Secondary activation of your obliques provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '80021201', '80021201-Resistance-Band-Wide-Stance-Anti-Rotation-Chop-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Secure the resistance band appropriately for Resistance Band Wide Stance Anti Rotation Chop. 2. Rotate your torso through the movement pattern for Resistance Band Wide Stance Anti Rotation Chop. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 55, 9, 8, TRUE, TRUE, 'general_exercise', 'Wide Stance Anti Rotation Chop', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 60, 4, 60, 85, 90, 50),
('7e50679a-f77a-40f5-846e-cc8ed1ddd66f', 'Triceps Dip (bench Leg)', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this dipping exercise for bigger arms. Your triceps, front delts work as secondary movers, adding to the training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '8121201', '08121201-Triceps-Dip-(bench-leg)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7e5b2a8f-35df-4e9b-8b18-6a0785fc1991', 'Reverse Vertical Hack Squat (Machine)', 'Legs', 'Hack Squat Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes work as secondary movers, adding to the training stimulus. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '57841201', '57841201-Lever-Reverse-Vertical-Hack-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Reverse Vertical Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'hack_squat', 'Lever Reverse Vertical Hack Squat', 'leg_press, squat, leg_extension', TRUE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('7e69a4c4-6c12-48c8-99aa-e636af00bc66', 'Standing Reach Up Back Rotation Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your back with this rotation stretch that helps restore range of motion. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '43211201', '43211201-Standing-Reach-Up-Back-Rotation-Stretch-(female)_B.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Reach Up Back Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Reach Up Back Rotation Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7e730860-f6bc-48b5-8ecb-26512593010a', 'Standing Bent Knee Calf Raise With A C - Alternating', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'The Standing Bent Knee Alternating Calf Raise With A C isolates your calf muscles through a raising motion. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '94111201', '94111201-Standing-Bent-Knee-Alternating-Calf-Raise-with-a-C.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Stand with feet about shoulder-width apart. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Bent Knee Calf Raise With A C - Alternating', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7e8e9002-40d5-4942-a4f8-03d996293e01', 'Diagonal Punch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'A challenging plyometric exercise, the Diagonal Punch builds reactive power and improves conditioning. Secondary activation of your shoulders provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '51121201', '51121201-Diagonal-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up in the starting position for Diagonal Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Diagonal Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7e95b335-80a7-428c-b22f-16be1db617e2', 'Shoulder Tap Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Shoulder Tap Push Up is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '38191201', '38191201-Shoulder-Tap-Push-up-(female)_Chest-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. Beneficial for overall chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Shoulder Tap Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ea17482-c694-4050-991e-720d606da8f7', 'Ceiling Look Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Ceiling Look Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '2501201', '02501201-Ceiling-Look-Stretch-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Move into the stretch position for Ceiling Look Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Ceiling Look Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7ea280bd-776e-423e-9586-2e839862d8bb', 'Crunch (leg Raise)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '2681201', '02681201-Crunch-(leg-raise)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Crunch', 'crunch, plank, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7eb84965-531a-458f-b3c8-265a5ab4c580', 'Romanian Deadlift Twist', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '77031201', '77031201-Romanian-Deadlift-Twist-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Push your hips back, lowering the weight along your legs with a flat back. 2. Lower until you feel a stretch in your hamstrings. 3. Drive hips forward to stand, squeezing glutes at the top. 4. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Romanian Deadlift Twist', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7ebde6f1-951f-4578-ac54-014ef070f141', 'Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '24781201', '24781201-Barbell-Lunge-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', 'Lunge', 'Push', 'Compound', 'Unilateral (Alternating)', NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('7ec4924f-2d59-419b-9ecc-ce00c505d660', '90 To 90 Side Bend Stretch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The 90 To 90 Side Bend Stretch provides a deep stretch for your hips, ideal for recovery and mobility work. The glutes assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105241201', '105241201-90-to-90-Side-Bend-Stretch-(male)_Stretching-MIRR.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Move into the stretch position for 90 To 90 Side Bend Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'side_bend', '90 To 90 Side Bend Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7eca30cb-bd94-428b-b60c-f2dd1b8bfa6a', 'Side Leg Swing (Wall Supported)', 'Full Body', 'Wall', '{"Full Body"}'::text[], '{}'::text[], 'The Wall Supported Side Leg Swing is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Include this in your routine for better mobility and reduced muscle tension.', '93541201', '93541201-Wall-Supported-Side-Leg-Swing-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Position yourself at the appropriate distance from a wall. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'leg_exercise', 'Wall Supported Side Leg Swing', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ed3c852-8d8b-4b87-b9ad-c0a3f08688b8', 'Seated Chin Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this movement movement. You''ll also feel your biceps working to support the movement. The seated position helps isolate the target muscles by removing momentum. Back development is crucial for pulling strength and overall upper body function.', '47811201', '47811201-Seated-Chin-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'pull_up', 'Seated Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ed6a494-da5a-4adb-97f7-e5c4ab870f1a', 'Head Supported Row (Kettlebell)', 'Back', 'Kettlebell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. A strong back improves posture, prevents injury, and balances pressing movements.', '68401201', '68401201-Kettlebell-Head-Supported-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriately weighted kettlebell for Kettlebell Head Supported Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'general_exercise', 'Head Supported Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('7edc15a9-8d25-4d8c-9fb8-1d72f4b334e7', 'Cocoons', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cocoons, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '2601201', '02601201-Cocoons_waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up in the starting position for Cocoons. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Cocoons', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7ee00e34-57c0-4a21-a747-a8b54a50e1f7', 'Standing Archer Arm Row - Alternating', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, rear delts provides additional muscle engagement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '96541201', '96541201-Standing-Archer-Alternate-Arm-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Begin in a standing position with good posture. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Archer Arm Row - Alternating', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7eefb4ee-7f1c-4a60-9734-30c151e04d34', 'Seated Pigeon Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Maintain proper breathing - exhale during the effort phase.', '63261201', '63261201-Seated-Pigeon-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Pigeon Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Pigeon Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7ef7e5e5-a6b6-42f1-b14e-773a3c79e464', 'Russian Twist Punch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Russian Twist Punch targets your obliques through a twisting motion, building rotational core strength. Secondary activation of your abs provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '58421201', '58421201-Russian-Twist-Punch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Rotate your torso through the movement pattern for Russian Twist Punch. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7f03a899-0ca7-42d1-8c51-df26618967bc', 'Hanging Leg Hip Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. The hip flexors, grip assist throughout the movement, making this a well-rounded exercise. Hanging adds a grip and core stability component to the exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '25511201', '25511201-Hanging-Leg-Hip-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Hanging Leg Hip Raise. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Hanging Leg Hip Raise', 'crunch, plank, v_up', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7f0b33a2-9b43-4aee-a459-852566537fbf', 'Deep Lunge Thoraic Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Deep Lunge Thoraic Stretch helps improve mobility and prevent stiffness. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Include this in your routine for better mobility and reduced muscle tension.', '81631201', '81631201-Deep-Lunge-Thoraic-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Deep Lunge Thoraic Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'stretch_general', 'Deep Lunge Thoraic Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7f0e7ae2-5435-4202-a07b-b5c096596c2f', 'Twist (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Cable Twist. Secondary activation of your abs provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '24511201', '24511201-Cable-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Twist. 2. Rotate your torso through the movement pattern for Cable Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('7f1876fc-b889-405b-aad2-10cf7aa66a2c', 'Planche Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts","Core"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The triceps, front delts, core assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '106641201', '106641201-Planche-Press-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'planche', 'Planche Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7f1d9ef3-5f7e-49eb-a762-16d6ce4639b0', 'Bent Leg Side Kick Kneeling (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Resistance Band Bent Leg Side Kick (kneeling), focusing on your core. Kneeling helps eliminate lower body momentum from the movement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '24181201', '24181201-Resistance-Band-Bent-Leg-Side-Kick-(kneeling)-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Bent Leg Side Kick. 2. Kneel on the floor (use a pad for comfort if needed). 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'leg_exercise', 'Bent Leg Side Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7f1f1325-e1e1-4f3a-8e3b-45501d6321d2', 'Lying Single Leg Curl (Machine)', 'Legs', 'Leg Curl Machine', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Lever Lying Single Leg Curl targets your hamstrings through a controlled curling motion. Secondary activation of your calves provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '44271201', '44271201-Lever-Lying-Single-Leg-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lying Single Leg Curl. 2. Lie down in the appropriate position for Lever Lying Single Leg Curl. 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 83, 7, 8, TRUE, TRUE, 'leg_curl', 'Lever Lying Single Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('7f261d89-3287-4221-8b9b-800b7ebfed1c', 'Bench Press - Single Weight (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. You''ll also feel your chest working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '70701201', '70701201-Dumbbell-Close-grip-Press-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Close Grip Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Execute the pressing motion for Dumbbell Close Grip Press, extending through the target muscles. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Press - Close Grip', 'Press - Close Grip', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('7f359073-0dec-45fa-a04a-7242442b944c', 'Incline Fly (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dumbbell Incline Fly is a flying exercise that targets your chest muscles. Your front delts work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3191201', '03191201-Dumbbell-Incline-Fly_Chest-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7f39510f-d689-4c06-bb95-e79ef41c8ef5', 'Behind Back Finger Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'The Dumbbell Behind Back Finger Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '37561201', '37561201-Dumbbell-Behind-Back-Finger-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Behind Back Finger Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Behind Back Finger Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('7f46b9ba-b66d-4246-8bb4-1461570d942f', 'Front Raise (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Barbell Front Raise, an effective shoulder raising exercise. Barbells enable bilateral loading for building raw strength. Shoulder development enhances both performance and upper body aesthetics. Excellent for pre-exhausting the target muscle before compound lifts.', '411201', '00411201-Barbell-Front-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Grip a barbell with hands at the appropriate width for Barbell Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', 'Shoulder Flexion', 'Push', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('7f497736-68d6-4207-ba6f-51f089df95a1', 'Seated Frog Half To Full Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Frog Half To Full Sit Up is a core movement exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '72551201', '72551201-Seated-Frog-Half-to-Full-Sit-up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Frog Half To Full Sit Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Seated Frog Half To Full Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7f4b49ae-d3b3-476b-91b0-813a3f43aed4', 'Decline Push Up (kneeling)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Decline Push Up (kneeling), an effective pushing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. A well-developed chest contributes to upper body strength and aesthetics.', '39351201', '39351201-Decline-Push-Up-(Kneeling)-(female)_Chest-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Decline Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7f4fc9b8-590b-4820-a8ca-eb0f1ea10545', 'Pull Up Neutral Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Pull Up (neutral Grip) is a pulling exercise that targets your latissimus dorsi for a wider back. Your biceps, upper back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '71161201', '71161201-Pull-up-(neutral-grip)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Use a neutral grip with palms facing each other. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('7f5d21bf-8f31-47d0-8107-cc5665b00212', 'Lying Side Straight Legs Reverse Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Side Straight Legs Reverse Crunch, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '104501201', '104501201-Lying-Side-Straight-Legs-Reverse-Crunch-(male)_Wa.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Lie on your side with your body aligned. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Lying Side Straight Legs Reverse Crunch', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7f61c08c-c00b-4ccc-a0f2-81663e2ab31a', 'Lying Straight Leg Reverse Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '77371201', '77371201-Lying-Straight-Leg-Reverse-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Straight Leg Reverse Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Lying Straight Leg Reverse Crunch', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('7fa0d828-7928-45b1-a67d-585ed7c1c91a', 'Bent Over Row - Neutral Grip (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Resistance Band Bent Over Neutral Grip Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Bending over allows gravity to provide resistance in a different plane. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '45701201', '45701201-Resistance-Band-Bent-Over-Neutral-Grip-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Secure the resistance band appropriately for Resistance Band Bent Over Neutral Grip Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'general_exercise', 'Bent Over Row - Neutral Grip', 'Bent Over Row - Neutral Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('7fa61aaf-900b-4973-a889-6469154ebc23', 'Incline Twisted Fly (Kettlebell)', 'Chest', 'Kettlebell, Incline Bench', '{"Chest"}'::text[], '{"Abs"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. The abs assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. The kettlebell grip position adds a unique training stimulus. A well-developed chest contributes to upper body strength and aesthetics.', '68271201', '68271201-Kettlebell-Incline-Twisted-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Twisted Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 81, 5, 7, FALSE, TRUE, 'russian_twist', 'Incline Twisted Fly', 'incline_bench_press, chest_fly, shoulder_press', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('7fab8d6f-ba3a-47e1-8f0d-44cdea4fc03d', 'Hamstring Curl With Punches (Gymnastic Rings) - Alternating', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Build power and athleticism with this high-intensity curling exercise that challenges your entire body. Secondary activation of your forearms provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '44371201', '44371201-Alternating-Hamstring-Curl-with-Punche_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'leg_curl', 'Hamstring Curl With Punches - Alternating', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('7fc94dc6-ebbe-445e-856b-bff512e33c1b', 'Bent Over Reverse Raise Skier (Barbell)', 'Shoulders', 'Barbell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Barbell Bent Over Reverse Raise (skier), an effective shoulder raising exercise. The bent over position requires core engagement to maintain a neutral spine. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '66091201', '66091201-Barbell-Bent-Over-Reverse-Raise-(skier)-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Grip a barbell with hands at the appropriate width for Barbell Bent Over Reverse Raise. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Raise the weight in the prescribed direction for Barbell Bent Over Reverse Raise. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'general_exercise', 'Bent Over Reverse Raise', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('7fd7bd68-92e0-474c-b393-2d95597bcfe3', 'Squat Twist (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Band Squat Twist targets your obliques through a squatting motion, building rotational core strength. You''ll also feel your abs working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Core strength is foundational for athletic performance and injury prevention.', '70491201', '70491201-Band-Squat-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Squat Twist. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'squat', 'Squat Twist', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('7fd92161-c90b-4318-8818-22e0b16c2c1d', 'Lat Lean To Cat Cow', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Target your spine with this movement stretch that helps restore range of motion. The core assist throughout the movement, making this a well-rounded exercise. Flexibility work like this enhances performance and prevents stiffness.', '85391201', '85391201-Lat-Lean-to-Cat-Cow-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Move into the stretch position for Lat Lean To Cat Cow. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Lat Lean To Cat Cow', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7fe6f52c-7999-47b1-b772-14b4b65ef3d1', 'Low To High Lunge Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Low To High Lunge Pose provides a deep stretch for your quads, ideal for recovery and mobility work. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '96701201', '96701201-Low-to-High-Lunge-Pose-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Low To High Lunge Pose. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 70, 2, 6, FALSE, TRUE, 'lunge', 'Low To High Lunge Pose', 'split_squat, step_up, squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7fe7eaf8-72b8-4660-8bbb-9724cbeb626c', 'Wide Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '1241201', '01241201-Barbell-Wide-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Wide Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Wide Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('7ff1ca58-c97b-40fb-926f-4b570168a34b', 'Calf Stretch With Rope', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted stretching exercise. Leg training boosts metabolism and builds functional, real-world strength.', '42771201', '42771201-Calf-Stretch-with-Rope-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Calf Stretch With Rope. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'calf_stretch', 'Calf Stretch With Rope', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('7ff9dc97-e783-4493-9d64-0902f54a562f', 'Standing Hip Flexion (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this flexion movement focusing on your full body. The standing position engages your core for stability. Cable resistance creates smooth, continuous muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '81911201', '81911201-Cable-Standing-Hip-Flexion-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Hip Flexion. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Flexion', 'squat, bench_press, deadlift', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8002ac45-605b-4cea-8a9e-46033b1e24da', 'Plyo Sit Squat (Against Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Strong legs are the foundation for athletic performance and functional fitness.', '6471201', '06471201-Plyo-Sit-Squat-(wall)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Position yourself at the appropriate distance from a wall. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Control the movement—avoid using momentum. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 77, 9, 8, TRUE, TRUE, 'squat', 'Plyo Sit Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('800c7cfc-a72b-458b-a4d9-3e055df57950', 'Seated Reverse Fly - Neutral Grip (Machine)', 'Shoulders', 'Fly Machine', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. The upper back assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Machine exercises are great for isolating muscles and training to failure safely. Shoulder development enhances both performance and upper body aesthetics.', '70011201', '70011201-Lever-Seated-Neutral-grip-Reverse-Fly-(female)_Sho.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Neutral Grip Reverse Fly. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. With a slight bend in your elbows, move the weight in a wide arc. 5. Squeeze your chest muscles at the center/top of the movement. 6. Return with control, feeling the stretch at the bottom. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'rear_delt', 'Lever Seated Reverse Fly - Neutral Grip', 'Lever Seated Reverse Fly - Neutral Grip', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('801faae6-ad0a-4fb6-810c-72da5c6d50bc', 'Penguin Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your full body with this stepping stretch that helps restore range of motion. Secondary activation of your quads provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '92701201', '92701201-Penguin-Step-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up a box or step platform at the appropriate height. 2. Move into the stretch position for Penguin Step. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Penguin Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8032eab9-0d13-4e4e-8fec-1f7ff8586b62', 'Runners Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension. Excellent for pre-exhausting the target muscle before compound lifts.', '63191201', '63191201-Runners-Stretch-(VERSION-2)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Move into the stretch position for Runners Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Runners Stretch', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('803a1f33-52c4-4d7c-8cec-04a99565430d', 'Weighted Lying Svend Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Weighted Lying Svend Press is a pressing exercise that targets your chest muscles. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '82911201', '82911201-Weighted-Lying-Svend-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Lie down in the appropriate position for Weighted Lying Svend Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squeeze_press', 'Weighted Lying Svend Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('803a70da-208a-49d3-aa52-7ef6998e16cc', 'Sumo Squat (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '86081201', '86081201-Resistance-Band-Sumo-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Secure the resistance band appropriately for Resistance Band Sumo Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('803f0c9b-0c48-4d59-be26-246c19a76452', 'Lying Oblique V Up', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your abs working to support the movement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '69231201', '69231201-Bodyweight-Lying-Oblique-V-Up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Lie down in the appropriate position for Bodyweight Lying Oblique V Up. 2. Set up in the starting position for Bodyweight Lying Oblique V Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'v_up', 'Lying Oblique V Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8045b8c6-4609-4ac9-b360-f1cf32cd0e80', 'Seated Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Cable Seated Crunch is a core crunching exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '2121201', '02121201-Cable-Seated-Crunch_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'crunch', 'Seated Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('80561ff1-4278-4763-9d9a-28a1cc508639', 'Weighted Dead Hang', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness. Excellent for pre-exhausting the target muscle before compound lifts.', '105761201', '105761201-Weighted-Dead-Hang-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Move into the stretch position for Weighted Dead Hang. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Weighted Dead Hang', 'pull_up, lat_pulldown, grip_training', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('8066644e-660b-46dd-843b-a3a637b8b9d3', 'Rolling Bridge', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This bridging exercise engages your abs for improved core stability and strength. The hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '6791201', '06791201-Rolling-Bridge-(female)_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Rolling Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('806c037d-a76f-46b2-a861-ba2534c7da4c', 'High Knee To Butt Kick', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Quads","Calves"}'::text[], 'The High Knee To Butt Kick is a cardiovascular exercise that improves endurance and heart health. Secondary activation of your hip flexors provides additional muscle engagement. Regular cardio training builds the aerobic base for better overall fitness.', '46341201', '46341201-High-Knee-to-Butt-Kick_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Set up in the starting position for High Knee To Butt Kick. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'glute_kickback', 'High Knee To Butt Kick', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('806c3386-388c-4c9e-be35-94db1ee48359', 'Elbow Flexion', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{}'::text[], 'The Elbow Flexion is a flexion exercise that isolates your biceps. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '106871201', '106871201-Elbow---Flexion-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Set up in the starting position for Elbow Flexion. 2. Execute the movement with proper form, focusing on your biceps. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Elbow Flexion', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('806cc9fc-1fb0-44a2-bb75-8b8d5608d40f', 'Two Legs Calf Raise (Band)', 'Legs', 'Resistance Band', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '39741201', '39741201-Band-Two-Legs-Calf-Raise---(Band-under-both-legs)-VERSION-2-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Two Legs Calf Raise. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'calf_raise', 'Two Legs Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
